  1198	    sync_read_fn_t on_sync_read, sync_write_fn_t on_sync_write,
  1199	    struct AV1LrSyncData *const lr_sync) {
  1200	  const int tile_w = tile_rect->right - tile_rect->left;
  1201	  const int ext_size = unit_size * 3 / 2;
  1202	  int x0 = 0, j = 0;
  1203	  while (x0 < tile_w) {
  1204	    int remaining_w = tile_w - x0;
  1205	    int w = (remaining_w < ext_size) ? remaining_w : unit_size;
  1206	
  1207	    limits->h_start = tile_rect->left + x0;
  1208	    limits->h_end = tile_rect->left + x0 + w;
  1209	    assert(limits->h_end <= tile_rect->right);
  1210	
  1211	    const int unit_idx = unit_idx0 + row_number * hunits_per_tile + j;
  1212	
  1213	    // No sync for even numbered rows
  1214	    // For odd numbered rows, Loop Restoration of current block requires the LR
  1215	    // of top-right and bottom-right blocks to be completed
  1216	
  1217	    // top-right sync
  1218	    on_sync_read(lr_sync, row_number, j, plane);
  1219	    if ((row_number + 1) < vunits_per_tile)
  1220	      // bottom-right sync
  1221	      on_sync_read(lr_sync, row_number + 2, j, plane);
  1222	
  1223	    on_rest_unit(limits, tile_rect, unit_idx, priv, tmpbuf, rlbs);
  1224	
  1225	    on_sync_write(lr_sync, row_number, j, hunits_per_tile, plane);
  1226	
  1227	    x0 += w;
  1228	    ++j;
  1229	  }
  1230	}
